  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Only shared formatting is contained here.
  3→package compact
  4→
  5→import (
  6→	"bufio"
  7→	"bytes"
  8→	"encoding/json"
  9→	"fmt"
 10→	"io"
 11→	"strings"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 14→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 15→)
 16→
 17→// Options provides metadata fields written to every output line.
 18→type Options struct {
 19→	Agent      string // e.g. "claude-code"
 20→	CLIVersion string // e.g. "0.42.0"
 21→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 22→}
 23→
 24→// compactMeta holds pre-computed JSON fragments for fields that are identical
 25→// on every output line, avoiding repeated marshaling.
 26→type compactMeta struct {
 27→	v          json.RawMessage
 28→	agent      json.RawMessage
 29→	cliVersion json.RawMessage
 30→}
 31→
 32→func newCompactMeta(opts Options) compactMeta {
 33→	return compactMeta{
 34→		v:          mustMarshal(1),
 35→		agent:      mustMarshal(opts.Agent),
 36→		cliVersion: mustMarshal(opts.CLIVersion),
 37→	}
 38→}
 39→
 40→// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
 41→//
 42→// The output format puts version, agent, and cli_version on every line,
 43→// merges streaming assistant fragments with the same message ID, and inlines
 44→// tool results into the preceding assistant's tool_use blocks:
 45→//
 46→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 47→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
 48→func Compact(content []byte, opts Options) ([]byte, error) {
 49→	truncated := transcript.SliceFromLine(content, opts.StartLine)
 50→	if truncated == nil {
 51→		truncated = []byte{}
 52→	}
 53→
 54→	if isOpenCodeFormat(truncated) {
 55→		return compactOpenCode(truncated, opts)
 56→	}
 57→
 58→	return compactJSONL(truncated, opts)
 59→}
 60→
 61→// droppedTypes are JSONL entry types that carry no parser-relevant data.
 62→var droppedTypes = map[string]bool{
 63→	"progress":              true,
 64→	"file-history-snapshot": true,
 65→	"queue-operation":       true,
 66→	"system":                true,
 67→}
 68→
 69→// userAliases maps JSONL type/role values to the canonical "user" kind.
 70→// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
 71→var userAliases = map[string]bool{
 72→	transcript.TypeUser: true,
 73→	"human":             true,
 74→}
 75→
 76→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 77→// JSONL transcript line. It checks the "type" field, then falls back to "role".
 78→// Returns "" for unrecognised or dropped entries.
 79→func normalizeKind(raw map[string]json.RawMessage) string {
 80→	kind := unquote(raw["type"])
 81→	if kind == "" {
 82→		kind = unquote(raw["role"])
 83→	}
 84→
 85→	if droppedTypes[kind] {
 86→		return ""
 87→	}
 88→	if userAliases[kind] {
 89→		return transcript.TypeUser
 90→	}
 91→	if kind == transcript.TypeAssistant {
 92→		return transcript.TypeAssistant
 93→	}
 94→	return ""
 95→}
 96→
 97→// linePreprocessor transforms a parsed JSONL line before conversion.
 98→// Used by agent-specific converters to normalize their format (e.g., Droid
 99→// envelope unwrapping) before the shared pipeline processes it.
100→type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
101→
102→// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
103→// compact format.
104→func compactJSONL(content []byte, opts Options) ([]byte, error) {
105→	return compactJSONLWith(content, opts, nil)
106→}
107→
108→// parsedEntry is an intermediate representation of a JSONL line used during
109→// the two-pass compact conversion.
110→type parsedEntry struct {
111→	kind        string // "user" or "assistant"
112→	ts          json.RawMessage
113→	id          string            // message ID (assistant only)
114→	userID      string            // prompt ID (user only, e.g. Claude's promptId)
115→	content     json.RawMessage   // stripped assistant content array, or nil
116→	userText    string            // extracted user text
117→	toolResults []toolResultEntry // user tool_result entries
118→}
119→
120→// compactJSONLWith converts JSONL transcripts into the compact format.
121→// It uses a two-pass approach:
122→//  1. Parse all lines into intermediate entries
123→//  2. Merge streaming assistant fragments (same msg ID), inline tool results
124→//     from user lines into preceding assistant tool_use blocks, and drop
125→//     tool-result-only user lines.
126→func compactJSONLWith(content []byte, opts Options, preprocess linePreprocessor) ([]byte, error) {
127→	meta := newCompactMeta(opts)
128→
129→	// Pass 1: parse all lines into intermediate entries.
130→	entries, err := parseJSONLEntries(content, preprocess)
131→	if err != nil {
132→		return nil, err
133→	}
134→
135→	// Pass 2: merge and emit.
136→	var result []byte
137→	for i := 0; i < len(entries); i++ {
138→		e := entries[i]
139→
140→		switch e.kind {
141→		case transcript.TypeAssistant:
142→			// Merge consecutive assistant entries with the same message ID.
143→			merged := e
144→			for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
145→				i++
146→				merged = mergeAssistantEntries(merged, entries[i])
147→			}
148→
149→			// Look ahead for user tool_result entries to inline.
150→			if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
151→				userEntry := entries[i+1]
152→				merged = inlineToolResults(merged, userEntry)
153→				i++ // consume the user tool_result entry
154→
155→				// If the consumed user entry also had text content, emit it
156→				// as a separate user line after the assistant.
157→				if userEntry.userText != "" {
158→					emitAssistant(&result, meta, merged)
159→					emitUser(&result, meta, userEntry)
160→					continue
161→				}
162→			}
163→
164→			if isEmptyContentArray(merged.content) {
165→				continue
166→			}
167→
168→			emitAssistant(&result, meta, merged)
169→
170→		case transcript.TypeUser:
171→			// User entries that are purely tool results were already consumed
172→			// by the assistant look-ahead above. If we reach one here it was
173→			// not preceded by an assistant with a matching tool_use, so emit
174→			// it only if it has text content.
175→			if hasToolResults(e) && e.userText == "" {
176→				continue
177→			}
178→			emitUser(&result, meta, e)
179→		}
180→	}
181→
182→	return result, nil
183→}
184→
185→func emitAssistant(result *[]byte, meta compactMeta, e parsedEntry) {
186→	b := marshalOrdered(
187→		"v", meta.v,
188→		"agent", meta.agent,
189→		"cli_version", meta.cliVersion,
190→		"type", mustMarshal(transcript.TypeAssistant),
191→		"ts", e.ts,
192→		"id", jsonStringOrNil(e.id),
193→		"content", e.content,
194→	)
195→	*result = append(*result, b...)
196→	*result = append(*result, '\n')
197→}
198→
199→func emitUser(result *[]byte, meta compactMeta, e parsedEntry) {
200→	block := marshalOrdered(
201→		"id", jsonStringOrNil(e.userID),
202→		"text", mustMarshal(e.userText),
203→	)
204→	contentJSON := mustMarshal([]json.RawMessage{block})
205→
206→	b := marshalOrdered(
207→		"v", meta.v,
208→		"agent", meta.agent,
209→		"cli_version", meta.cliVersion,
210→		"type", mustMarshal(transcript.TypeUser),
211→		"ts", e.ts,
212→		"content", contentJSON,
213→	)
214→	*result = append(*result, b...)
215→	*result = append(*result, '\n')
216→}
217→
218→// parseJSONLEntries parses all JSONL lines into intermediate entries,
219→// filtering dropped types and malformed lines.
220→func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
221→	reader := bufio.NewReader(bytes.NewReader(content))
222→	var entries []parsedEntry
223→
224→	for {
225→		lineBytes, err := reader.ReadBytes('\n')
226→		if err != nil && err != io.EOF {
227→			return nil, fmt.Errorf("reading JSONL line: %w", err)
228→		}
229→
230→		if len(bytes.TrimSpace(lineBytes)) > 0 {
231→			if e, ok := parseLine(lineBytes, preprocess); ok {
232→				entries = append(entries, e)
233→			}
234→		}
235→
236→		if err == io.EOF {
237→			break
238→		}
239→	}
240→
241→	return entries, nil
242→}
243→
244→// parseLine converts a single JSONL line into a parsedEntry.
245→// Returns ok=false for dropped/malformed lines.
246→func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
247→	var raw map[string]json.RawMessage
248→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
249→		return parsedEntry{}, false
250→	}
251→
252→	if preprocess != nil {
253→		raw = preprocess(raw)
254→	}
255→
256→	kind := normalizeKind(raw)
257→	if kind == "" {
258→		return parsedEntry{}, false
259→	}
260→
261→	e := parsedEntry{
262→		kind: kind,
263→		ts:   raw["timestamp"],
264→	}
265→
266→	msg := parseMessage(raw)
267→
268→	switch kind {
269→	case transcript.TypeAssistant:
270→		if msg != nil {
271→			e.id = unquote(msg["id"])
272→			if contentRaw, ok := msg["content"]; ok {
273→				e.content = stripAssistantContent(contentRaw)
274→			}
275→		}
276→
277→	case transcript.TypeUser:
278→		e.userID = unquote(raw["promptId"])
279→		if msg != nil {
280→			if contentRaw, ok := msg["content"]; ok {
281→				text, toolResults := extractUserContent(contentRaw)
282→				e.userText = text
283→				e.toolResults = toolResults
284→			}
285→		}
286→		// Also check toolUseResult.stdout which may have the output.
287→		if turRaw, ok := raw["toolUseResult"]; ok {
288→			var tur map[string]json.RawMessage
289→			if json.Unmarshal(turRaw, &tur) == nil {
290→				if stdout := unquote(tur["stdout"]); stdout != "" {
291→					switch len(e.toolResults) {
292→					case 0:
293→						// Keep compatibility with transcripts that only include toolUseResult.
294→						e.toolResults = []toolResultEntry{{
295→							output: stdout,
296→						}}
297→					case 1:
298→						// toolUseResult is a single envelope for one tool call.
299→						e.toolResults[0].output = stdout
300→					}
301→				}
302→			}
303→		}
304→	}
305→
306→	return e, true
307→}
308→
309→// mergeAssistantEntries combines two assistant entries with the same message ID.
310→// Content arrays are concatenated; the later timestamp wins.
311→func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
312→	merged := a
313→	merged.ts = b.ts
314→
315→	var aBlocks, bBlocks []json.RawMessage
316→	_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
317→	_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
318→	all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
319→	if data, err := json.Marshal(all); err == nil {
320→		merged.content = data
321→	}
322→
323→	return merged
324→}
325→
326→// inlineToolResults adds "result" fields to matching tool_use blocks in the
327→// assistant entry's content, using outputs from user tool_result entries.
328→func inlineToolResults(assistant, user parsedEntry) parsedEntry {
329→	var blocks []map[string]json.RawMessage
330→	if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
331→		return assistant
332→	}
333→
334→	for _, tr := range user.toolResults {
335→		// Find the tool_use block matching this tool_use_id.
336→		idx := -1
337→		for i := len(blocks) - 1; i >= 0; i-- {
338→			if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
339→				if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
340→					idx = i
341→					break
342→				}
343→			}
344→		}
345→		// No matching tool_use block: do not attach a result to unrelated content.
346→		if idx == -1 {
347→			continue
348→		}
349→
350→		status := "success"
351→		if tr.isError {
352→			status = "error"
353→		}
354→		resultObj := marshalOrdered(
355→			"output", mustMarshal(tr.output),
356→			"status", mustMarshal(status),
357→		)
358→		blocks[idx]["result"] = resultObj
359→	}
360→
361→	if data, err := json.Marshal(blocks); err == nil {
362→		assistant.content = data
363→	}
364→
365→	return assistant
366→}
367→
368→// jsonStringOrNil returns a JSON-encoded string, or nil if s is empty.
369→func jsonStringOrNil(s string) json.RawMessage {
370→	if s == "" {
371→		return nil
372→	}
373→	return mustMarshal(s)
374→}
375→
376→// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
377→func isEmptyContentArray(raw json.RawMessage) bool {
378→	var arr []json.RawMessage
379→	return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
380→}
381→
382→func hasToolResults(e parsedEntry) bool {
383→	return len(e.toolResults) > 0
384→}
385→
386→type toolResultEntry struct {
387→	toolUseID string
388→	output    string
389→	isError   bool
390→}
391→
392→// parseMessage extracts and parses the "message" field from a JSONL transcript
393→// line. All JSONL agents nest content inside a "message" object.
394→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
395→	msgRaw, ok := raw["message"]
396→	if !ok {
397→		return nil
398→	}
399→	var msg map[string]json.RawMessage
400→	if json.Unmarshal(msgRaw, &msg) == nil {
401→		return msg
402→	}
403→	return nil
404→}
405→
406→// extractUserContent separates user message content into text and tool_result entries.
407→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
408→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
409→	var str string
410→	if json.Unmarshal(contentRaw, &str) == nil {
411→		return textutil.StripIDEContextTags(str), nil
412→	}
413→
414→	var blocks []map[string]json.RawMessage
415→	if json.Unmarshal(contentRaw, &blocks) != nil {
416→		return "", nil
417→	}
418→
419→	var texts []string
420→	var toolResults []toolResultEntry
421→
422→	for _, block := range blocks {
423→		blockType := unquote(block["type"])
424→
425→		if blockType == "tool_result" {
426→			var isErr bool
427→			if raw, ok := block["is_error"]; ok {
428→				_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
429→			}
430→			toolResults = append(toolResults, toolResultEntry{
431→				toolUseID: unquote(block["tool_use_id"]),
432→				output:    unquote(block["content"]),
433→				isError:   isErr,
434→			})
435→			continue
436→		}
437→
438→		if blockType == transcript.ContentTypeText {
439→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
440→			if stripped != "" {
441→				texts = append(texts, stripped)
442→			}
443→		}
444→	}
445→
446→	return strings.Join(texts, "\n\n"), toolResults
447→}
448→
449→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
450→	var str string
451→	if json.Unmarshal(contentRaw, &str) == nil {
452→		return contentRaw
453→	}
454→
455→	var blocks []map[string]json.RawMessage
456→	if json.Unmarshal(contentRaw, &blocks) != nil {
457→		return contentRaw
458→	}
459→
460→	result := make([]map[string]json.RawMessage, 0, len(blocks))
461→	for _, block := range blocks {
462→		blockType := unquote(block["type"])
463→
464→		if blockType == "thinking" || blockType == "redacted_thinking" {
465→			continue
466→		}
467→
468→		if blockType == transcript.ContentTypeToolUse {
469→			stripped := make(map[string]json.RawMessage)
470→			copyField(stripped, block, "type")
471→			copyField(stripped, block, "id")
472→			copyField(stripped, block, "name")
473→			copyField(stripped, block, "input")
474→			result = append(result, stripped)
475→			continue
476→		}
477→
478→		result = append(result, block)
479→	}
480→
481→	b, err := json.Marshal(result)
482→	if err != nil {
483→		return contentRaw
484→	}
485→	return b
486→}
487→
488→// marshalOrdered produces a JSON object with keys in the given order.
489→// Pairs with nil values are omitted.
490→func marshalOrdered(pairs ...interface{}) []byte {
491→	var buf bytes.Buffer
492→	buf.WriteByte('{')
493→	first := true
494→	for i := 0; i < len(pairs)-1; i += 2 {
495→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
496→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
497→		if val == nil {
498→			continue
499→		}
500→		if !first {
501→			buf.WriteByte(',')
502→		}
503→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
504→		buf.Write(keyJSON)
505→		buf.WriteByte(':')
506→		buf.Write(val)
507→		first = false
508→	}
509→	buf.WriteByte('}')
510→	return buf.Bytes()
511→}
512→
513→// mustMarshal marshals v to JSON, panicking on error (which should never
514→// happen for the primitive types we pass).
515→func mustMarshal(v interface{}) json.RawMessage {
516→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
517→	return b
518→}
519→
520→// copyField copies a single key from src to dst if it exists.
521→func copyField(dst, src map[string]json.RawMessage, key string) {
522→	if v, ok := src[key]; ok {
523→		dst[key] = v
524→	}
525→}
526→
527→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
528→func unquote(raw json.RawMessage) string {
529→	var s string
530→	if json.Unmarshal(raw, &s) == nil {
531→		return s
532→	}
533→	return ""
534→}
