431→func nonEmptyLines(data []byte) []string {
432→	var lines []string
433→	for _, line := range strings.Split(string(data), "\n") {
434→		if strings.TrimSpace(line) != "" {
435→			lines = append(lines, line)
436→		}
437→	}
438→	return lines
439→}
