441→// assertJSONLines compares actual output lines against expected JSON strings,
442→// using semantic JSON equality (order-independent for object keys).
443→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
444→	t.Helper()
445→
446→	actualLines := nonEmptyLines(actual)
447→
448→	if len(expected) == 0 && len(actualLines) == 0 {
449→		return
450→	}
451→
452→	if len(actualLines) != len(expected) {
453→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
454→	}
455→
456→	for i := range expected {
457→		var got, want interface{}
458→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
459→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
460→		}
461→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
462→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
463→		}
464→		if !reflect.DeepEqual(got, want) {
465→			prettyGot, _ := json.MarshalIndent(got, "", "  ")   //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
466→			prettyWant, _ := json.MarshalIndent(want, "", "  ") //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
467→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
468→		}
469→	}
470→}
