  6→// Extract text and image content from message content (string or array of blocks)
  7→interface ExtractedContent {
  8→  text: string
  9→  images: Array<{ mediaType: string; data: string }>
 10→  hasToolResults: boolean
 11→}
 12→
 13→// Pattern for image references that Claude Code outputs when it "reads" an image.
 14→// These are text markers like "[Image: source: /path/to/file.png]" - not actual image data.
 15→// We strip these since the actual images are rendered from base64 content blocks.
 16→const IMAGE_REFERENCE_PATTERN = /\[Image: source: [^\]]+\]/g
 17→
 18→function extractTextContent(content: unknown): ExtractedContent {
 19→  if (typeof content === "string") {
 20→    return {
 21→      text: content.replace(IMAGE_REFERENCE_PATTERN, "").trim(),
 22→      images: [],
 23→      hasToolResults: false,
 24→    }
 25→  }
 26→  if (!Array.isArray(content)) {
 27→    return { text: "", images: [], hasToolResults: false }
 28→  }
 29→
 30→  let text = ""
 31→  const images: Array<{ mediaType: string; data: string }> = []
 32→  let hasToolResults = false
 33→
 34→  for (const block of content) {
 35→    if (typeof block === "object" && block !== null) {
 36→      const b = block as Record<string, unknown>
 37→      if (b.type === "text") {
 38→        text += (b.text as string) || ""
 39→      } else if (b.type === "tool_result") {
 40→        hasToolResults = true
 41→      } else if (b.type === "image") {
 42→        const source = b.source as Record<string, unknown> | undefined
 43→        if (source?.type === "base64" && source.data && source.media_type) {
 44→          images.push({
 45→            mediaType: source.media_type as string,
 46→            data: source.data as string,
 47→          })
 48→        }
 49→      }
 50→    }
 51→  }
 52→  // Strip image reference markers from text (see comment above)
 53→  text = text.replace(IMAGE_REFERENCE_PATTERN, "").trim()
