 91→/**
 92→ * Parse Claude Code JSONL transcript into TranscriptMessage[].
 93→ * Returns a natural conversation: user prompt -> final assistant reply (before next user prompt).
 94→ * Also extracts tool calls made during each assistant turn.
 95→ */
 96→function parseClaudeCodeTranscript(jsonlContent: string): TranscriptMessage[] {
 97→  const lines = jsonlContent.split("\n").filter((line) => line.trim())
 98→
 99→  // Internal types for collecting data
100→  type InternalMessage = {
101→    role: "user" | "assistant"
102→    content: string
103→    images: Array<{ mediaType: string; data: string }>
104→    timestamp: string
105→    id: string
106→  }
107→
108→  // Collect all tool_use records: id -> { name, input, timestamp }
109→  type ToolUseData = Omit<ToolCall, "id" | "result">
110→  const toolUseById = new Map<string, ToolUseData>()
111→
112→  // Collect all tool_result records: tool_use_id -> result metadata
113→  const toolResultById = new Map<string, ToolCallResult>()
114→
115→  // First pass: collect tool_use and tool_result records
116→  for (const line of lines) {
117→    let parsed: Record<string, unknown>
118→    try {
119→      parsed = JSON.parse(line)
120→    } catch {
121→      continue
122→    }
123→
124→    const type = parsed.type as string | undefined
125→    const message = parsed.message as Record<string, unknown> | undefined
126→    const timestamp = (parsed.timestamp as string) || new Date().toISOString()
127→
128→    if (type === "assistant" && message?.content) {
129→      // Check for tool_use blocks in assistant messages
130→      const toolUses = extractToolUseBlocks(message.content)
131→      for (const tu of toolUses) {
132→        toolUseById.set(tu.id, {
133→          name: tu.name,
134→          input: tu.input,
135→          timestamp,
136→        })
137→      }
138→    } else if (type === "user" && message?.content) {
139→      // Check for tool_result blocks (they come as "user" type messages)
140→      const content = message.content as unknown[]
141→      if (Array.isArray(content)) {
142→        for (const block of content) {
143→          if (typeof block === "object" && block !== null) {
