159→  const assistantByRequestId = new Map<string, number>()
160→
161→  // Track tool calls in the current turn (between user messages)
162→  // Key is the index in messages array where we'll eventually attach them
163→  const toolCallsPerTurn: ToolCall[] = []
164→
165→  for (const line of lines) {
