194→          toolCallsPerTurn.push(toolCall)
195→        }
196→      }
197→
198→      // Also extract text content for the message
199→      const { text, images } = extractTextContent(message.content)
200→      const content = text.trim()
201→      const requestId = (parsed.requestId as string) || (message.id as string)
202→      if (!requestId) continue
203→
204→      const existingIdx = assistantByRequestId.get(requestId)
205→      if (existingIdx !== undefined) {
206→        // Streaming update: replace with latest content
207→        if (content) {
208→          messages[existingIdx].content = content
209→        }
210→        if (images.length > 0) {
211→          messages[existingIdx].images = images
212→        }
213→        // Always advance timestamp so tool calls from later streaming
214→        // lines (e.g. tool_use arriving after text) fall within the
