229→      const { text, images, hasToolResults } = extractTextContent(message.content)
230→      const content = text.trim()
231→
232→      // Skip user messages that are only tool results and have no text/images
233→      if ((!content && images.length === 0) || hasToolResults) continue
234→
235→      messages.push({
236→        role: "user",
237→        content,
238→        images,
239→        timestamp,
240→        id: (parsed.uuid as string) || crypto.randomUUID(),
241→      })
242→    }
243→  }
244→
245→  // Sort by timestamp
246→  messages.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
247→
248→  // Sort tool calls by timestamp for proper ordering
249→  toolCallsPerTurn.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
250→
251→  // Build result: keep ALL assistant messages with content between user messages.
252→  // Claude Code can emit multiple assistant responses (text → tool calls → summary)
253→  // before the user responds — each is a separate API call with its own requestId.
254→  // Attach tool calls to the assistant message they follow (by timestamp range).
255→  const result: TranscriptMessage[] = []
256→  // Collect all assistants with content between user messages
257→  let pendingAssistants: InternalMessage[] = []
258→  let lastUserTimestamp: string | null = null
259→
260→  const hasContent = (m: InternalMessage) => m.content || m.images.length > 0
261→
262→  // Helper to get tool calls between two timestamps
263→  const getToolCallsInRange = (startTs: string | null, endTs: string): ToolCall[] => {
