267→      const tcTime = new Date(tc.timestamp).getTime()
268→      if (startTime === null) {
269→        return tcTime <= endTime
270→      }
271→      return tcTime > startTime && tcTime <= endTime
272→    })
273→  }
274→
275→  const flushAssistants = () => {
276→    for (let i = 0; i < pendingAssistants.length; i++) {
277→      const assistant = pendingAssistants[i]
278→      // Tool calls range: from previous assistant's timestamp (or last user) to this assistant's timestamp
279→      const rangeStart = i === 0 ? lastUserTimestamp : pendingAssistants[i - 1].timestamp
280→      const turnToolCalls = getToolCallsInRange(rangeStart, assistant.timestamp)
281→      result.push({
282→        ...assistant,
283→        images: assistant.images.length > 0 ? assistant.images : undefined,
284→        toolCalls: turnToolCalls,
285→      })
286→    }
287→    pendingAssistants = []
288→  }
289→
290→  for (const msg of messages) {
291→    if (msg.role === "user") {
292→      flushAssistants()
