294→        ...msg,
295→        images: msg.images.length > 0 ? msg.images : undefined,
296→      })
297→      lastUserTimestamp = msg.timestamp
298→    } else if (hasContent(msg)) {
299→      pendingAssistants.push(msg)
300→    }
301→  }
